    body: '수열 {<span class="m">aₙ</span>}이 <span class="m">a₁ = 7</span>이고, 모든 자연수 <span class="m">n</span>에 대하여<br><span class="m">aₙ</span>이 짝수이면 <span class="m">aₙ₊₁ = aₙ / 2</span>, 홀수이면 <span class="m">aₙ₊₁ = aₙ + 5</span><br>를 만족시킬 때, <span class="m">a₁ + a₂ + ⋯ + a₂₀</span>의 값을 구하시오.',
