    body: '글의 흐름으로 보아, 주어진 문장이 들어가기에 가장 적절한 곳은?<div class="bogi">In other words, cramming works for tomorrow but not for next month.</div><div class="passage">( ① ) Most students prepare for an exam by studying for many hours the night before. ( ② ) It feels efficient: the information is fresh when the test begins, and scores are often decent. ( ③ ) Ask the same students a month later, however, and much of what they learned is gone. ( ④ ) Researchers have found that the same material spread over several short sessions is remembered far longer. ( ⑤ ) The gaps between sessions seem to be the key, as they give the brain time to store what it has learned.</div>',
