    level: 3,
    slot: '공통 · 5지선다',
    body: '삼각형 ABC에서 <span class="m">BC = 7</span>, <span class="m">CA = 5</span>, <span class="m">AB = 3</span>일 때, 각 A의 크기는?',
    type: 'choice',
    choices: ['60°', '90°', '120°', '135°', '150°'],
    answer: 3,
