    body: '동전 4개를 동시에 던질 때, 앞면이 적어도 하나 나올 확률은 <span class="m">q/p</span>이다. <span class="m">p + q</span>의 값을 구하시오. (단, <span class="m">p, q</span>는 서로소인 자연수)',
    type: 'num',
    answer: 31,
