    subject: 'math',
    unit: 'alg',
    kind: 'real',
    points: 3,
    level: 3,
    slot: '공통 · 단답',
    body: '수열 {<span class="m">aₙ</span>}의 첫째항부터 제<span class="m">n</span>항까지의 합이 <span class="m">Sₙ = 2ⁿ − 1</span>일 때, <span class="m">a₆</span>의 값을 구하시오.',
