    body: '두 사건 <span class="m">A, B</span>에 대하여 <span class="m">P(A) = 0.5</span>, <span class="m">P(B) = 0.4</span>, <span class="m">P(A ∪ B) = 0.7</span>일 때, <span class="m">P(A ∩ B)</span>는?',
