    body: '다음 글의 주제로 가장 적절한 것은?<div class="passage">Many people try to change their lives with big resolutions, such as exercising for an hour every day. These plans often fail within weeks because they demand too much willpower at once. A more reliable approach is to start with an action so small that it feels almost silly, like putting on running shoes or doing two push-ups. Once the small action becomes automatic, it can be expanded step by step. Over time, these tiny beginnings add up to lasting change.</div>',
