    body: '[1~4] 다음 글을 읽고 물음에 답하시오.<div class="passage" style="font-style:normal">인터넷으로 주고받는 정보는 중간에서 누군가 엿볼 수 있으므로 암호화가 필요하다. 암호화는 평문을 키를 이용해 알아볼 수 없는 암호문으로 바꾸는 일이고, 복호화는 암호문을 다시 평문으로 되돌리는 일이다. 가장 단순한 방식은 암호화와 복호화에 같은 키를 쓰는 대칭 키 방식이다. 이 방식은 계산이 빨라 많은 양의 데이터를 처리하기에 알맞다. 그러나 주고받는 두 사람이 같은 키를 미리 나누어 가져야 하는데, 그 키를 안전하게 전달하는 일 자체가 어렵다. 전달 도중 키를 도둑맞으면 그 뒤의 암호문이 모두 풀리기 때문이다.<br>이 문제를 풀기 위해 등장한 것이 공개 키 방식이다. 이 방식에서는 한 사람이 서로 짝을 이루는 두 개의 키, 곧 누구에게나 알려 주는 공개 키와 자신만 간직하는 개인 키를 만든다. 공개 키로 암호화한 내용은 그 짝인 개인 키로만 복호화할 수 있다. 따라서 갑에게 비밀 메시지를 보내려는 사람은 갑의 공개 키로 암호화해 보내면 되고, 중간에 이를 가로챈 사람은 갑의 개인 키가 없으므로 내용을 읽을 수 없다. 공개 키로부터 개인 키를 알아내는 일은 계산상 매우 어렵도록 설계되어 있다. 널리 쓰이는 RSA 방식은 매우 큰 수를 소인수분해하기 어렵다는 점에 기대고 있다.<br>반대로 개인 키로 암호화한 내용은 그 짝인 공개 키로 복호화할 수 있다. 공개 키는 누구나 가질 수 있으므로 이것은 비밀을 지키는 데는 쓸모가 없다. 하지만 그 암호문은 개인 키를 가진 사람만 만들 수 있으므로, 누가 보냈는지를 확인하는 데 쓰인다. 이를 전자 서명이라 한다. 다만 공개 키 방식은 대칭 키 방식보다 계산이 훨씬 느리다. 그래서 실제 통신에서는 공개 키 방식으로 대칭 키만 안전하게 전달한 뒤, 본래의 데이터는 그 대칭 키로 암호화하여 주고받는 경우가 많다.</div>윗글을 바탕으로 할 때, 갑의 공개 키로 암호화된 메시지를 을이 중간에서 가로챘을 경우에 대한 추론으로 가장 적절한 것은?',
