    body: '다음 글의 주제로 가장 적절한 것은?<div class="passage">On a summer evening, a person driving from the countryside into a large city may notice the temperature rising by several degrees. This effect, known as the urban heat island, has several causes. Dark surfaces such as asphalt roads and rooftops absorb sunlight during the day and slowly release that heat after sunset, keeping the city warm long into the night. Buildings packed closely together trap warm air, while air conditioners and cars add heat of their own. In the countryside, by contrast, plants and moist soil cool the air as water evaporates from them. Fortunately, cities are not powerless against the problem. Planting trees along streets, creating parks, and painting roofs in light colors that reflect sunlight have all been shown to lower local temperatures.</div>',
