    level: 2,
    slot: '글의 요지',
    body: '다음 글의 요지로 가장 적절한 것은?<div class="passage">Many students hesitate to ask questions in class because they fear looking less capable than their classmates. They would rather struggle alone for hours than admit, even for a moment, that they do not understand. Yet the people who learn fastest are rarely those who never need help; they are those who know when and how to ask for it. A well-timed question can save an afternoon of confusion, and it often helps others in the room who were too shy to speak. Moreover, teachers generally welcome questions, because questions reveal which parts of a lesson need more explanation. Seen this way, asking for help is not a confession of weakness but a sign that a learner is taking responsibility for his or her own progress.</div>',
    type: 'choice',
