    slot: '주제 · 오답 많은 유형',
    body: '다음 글의 주제로 가장 적절한 것은?<div class="passage">Suppose a movie theater sells small popcorn for $3 and large popcorn for $7. Many customers, unwilling to spend so much, choose the small size. Now imagine that the theater adds a medium size for $6.50. Hardly anyone buys it, yet sales of the large size rise. The medium option was never really meant to be chosen. Its purpose is to make the large one look like a bargain: for just fifty cents more, customers get much more popcorn. Marketers call this kind of option a “decoy,” because it exists mainly to change how the other options appear. The effect shows that our choices are rarely made in isolation. Instead of judging each item on its own value, we tend to compare it with whatever happens to be next to it.</div>',
