    body: '다음 글에서 전체 흐름과 관계 <b>없는</b> 문장은?<div class="passage">Camels are remarkably well suited to life in the desert, where food and water are scarce and sandstorms are common. ① Their humps store fat, not water as many people believe, and this fat can be broken down for energy when food is scarce. ② Camels have been used by humans to carry goods across deserts for thousands of years, and their caravans once linked distant markets. ③ They can also go for long periods without drinking, and when they do find water, they can take in a huge amount in a very short time. ④ Their long eyelashes and nostrils that can close protect them from blowing sand. ⑤ Even their wide, padded feet help them walk on soft sand without sinking, spreading their weight over a larger area.</div>',
