    level: 3,
    slot: '요약문',
    body: '다음 글의 내용을 한 문장으로 요약할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것은?<div class="passage">In a classic experiment, college students took part in a discussion over an intercom, each sitting alone in a separate room. Partway through, one of the voices began to sound as if its speaker were having a seizure and called out for help. When participants believed that they were the only other person who could hear him, most of them quickly left their rooms to find help. When they believed that several other people were also listening, however, far fewer did so, and those who did act took much longer. The researchers concluded that the participants were not simply cold or uncaring. Rather, when many people witness an emergency, each one tends to feel that someone else will step in.</div><div class="bogi">The <b>(A)</b> of other people can <b>(B)</b> an individual’s sense of responsibility to act in an emergency.</div>',
