    slot: '어법 · 오답 많은 유형',
    body: '다음 글의 밑줄 친 부분 중, 어법상 <b>틀린</b> 것은?<div class="passage">Animals that live in large groups face a puzzle: how can so many individuals move together without <u>① crash</u> into one another? Starlings, for example, form flocks of thousands of birds <u>② that</u> twist and turn across the evening sky like a single living shape. Scientists once suspected that a leader must be directing the flock, but computer models have shown that no leader is needed. Each bird simply pays attention to a handful of its nearest neighbors, <u>③ adjusting</u> its speed and direction to match theirs. When one bird turns to avoid a falcon, the change spreads through the flock so quickly that the whole group appears <u>④ to move</u> as one. What looks like careful planning is <u>⑤ actually</u> the result of many small, local decisions.</div>',
