    body: '다음 글의 밑줄 친 부분 중, 어법상 <b>틀린</b> 것은?<div class="passage">In many cities, the bicycle is making a comeback. For decades, urban planners designed streets mainly for cars, leaving little room for anyone else. Today, separate lanes <u>① protected</u> from car traffic have made cycling feel safer, and bike-sharing systems allow people to ride without <u>② owning</u> a bicycle at all. As a result, the number of people who ride to work <u>③ have</u> grown steadily in a number of European cities. City officials welcome this trend, <u>④ which</u> reduces both traffic jams and air pollution. Still, cycling remains difficult in neighborhoods with steep hills, where even experienced riders find the daily climb <u>⑤ exhausting</u>. Electric bicycles, which give riders a gentle push, may help solve this problem by making such hills far easier to manage.</div>',
