    body: '다음 글의 밑줄 친 부분 중, 어법상 <b>틀린</b> 것은?<div class="passage">Long before clocks were common, people <u>① relied</u> on the sun to tell the time. A simple stick placed upright in the ground casts a shadow <u>② whose</u> length and direction change as the sun moves across the sky. By marking the position of the shadow at different hours, early people created sundials, some of <u>③ which</u> were remarkably accurate. Sundials, however, had an obvious weakness: they were useless at night and on cloudy days. Water clocks, <u>④ measuring</u> time by the steady flow of water from a container, solved part of the problem. Yet it was not until mechanical clocks appeared in medieval Europe <u>⑤ what</u> towns began to organize daily life around a bell that struck every hour.</div>',
