    slot: '어휘',
    body: '다음 글의 밑줄 친 부분 중, 문맥상 낱말의 쓰임이 적절하지 <b>않은</b> 것은?<div class="passage">Many people who start exercising believe that the harder and more often they train, the faster they will improve. In fact, muscles do not grow stronger during a workout itself. Intense exercise causes tiny <u>① damage</u> to muscle fibers, and it is during the hours and days of rest that follow that the body <u>② repairs</u> these fibers and makes them slightly stronger than before. Without enough rest, this process is <u>③ interrupted</u>, and the muscles never get a chance to recover fully. Athletes who train hard every day without a break therefore often find that their performance <u>④ improves</u>, and they also become more likely to get injured. Rest, then, is not time <u>⑤ wasted</u> but an essential part of training.</div>',
