    body: '다음 글의 밑줄 친 부분 중, 문맥상 낱말의 쓰임이 적절하지 <b>않은</b> 것은?<div class="passage">In 1859, a settler in Australia released about two dozen rabbits onto his land so that he could hunt them for sport. The animals found conditions there extremely <u>① favorable</u>: food was plentiful, the winters were mild, and natural predators were <u>② abundant</u>. Rabbits breed quickly, and within a few decades they had <u>③ spread</u> across much of the continent. Their numbers grew into the hundreds of millions. They stripped the land of grasses and young plants, leaving the soil <u>④ exposed</u> to erosion, and they competed with native animals for food. Later attempts to control them, including the building of fences stretching thousands of kilometers, proved largely <u>⑤ ineffective</u>. Even today, rabbits remain one of the most damaging introduced animals in the country.</div>',
