    body: '다음 글에서 필자가 주장하는 바로 가장 적절한 것은?<div class="passage">When a zipper breaks or a chair leg comes loose, most of us no longer think about fixing it. Replacements are cheap, and repair seems to require skills we never learned. Yet every object we throw away carries a hidden cost: the materials, energy, and labor that went into making it are wasted, and the item usually ends up in a landfill. Repairing things also offers rewards that buying new ones cannot. Learning to sew on a button or tighten a loose hinge builds confidence and a sense of control over our surroundings. These skills are not difficult; most can be learned in an afternoon from a neighbor or an online video. Before reaching for your wallet, then, it is worth reaching for a screwdriver or a needle. We should treat the ability to repair everyday objects as a basic life skill and make the effort to learn it.</div>',
