    body: '밑줄 친 <u>arrive everywhere but know nowhere</u>가 다음 글에서 의미하는 바로 가장 적절한 것은?<div class="passage">Not long ago, finding your way around a new city meant studying a paper map, noticing landmarks, and occasionally getting lost. Today, a calm voice from our phones tells us exactly when to turn, and we rarely take a wrong step. This convenience comes at a price, however. When we simply follow instructions, we stop paying attention to where we are. We do not notice that the bakery is two blocks from the station or that the river runs along the east side of town. Some studies suggest that people who rely heavily on navigation apps form weaker mental maps of the places they pass through. In a sense, we <u>arrive everywhere but know nowhere</u>. The places we visit remain a series of disconnected points, linked only by a line on a screen that disappears the moment we put the phone away.</div>',
