    body: '밑줄 친 <u>the drawer quietly writes part of the story</u>가 다음 글에서 의미하는 바로 가장 적절한 것은?<div class="passage">Imagine that twenty research teams separately test whether a certain vitamin improves memory. Nineteen find no effect, and one, purely by chance, finds a small improvement. Which result is most likely to appear in a journal? Studies that report something new and positive are far more attractive to editors and readers than studies that report nothing. As a result, many researchers whose experiments show no effect simply put their data away and move on to the next project. Scientists call this the “file drawer problem.” The danger is not that any single study is dishonest; each one may have been carried out with great care. The danger is that the published record shows only the lucky result, while the nineteen others sit unseen. Anyone who reads the journals will reasonably conclude that the vitamin works. In this way, <u>the drawer quietly writes part of the story</u>.</div>',
