    body: '다음 글의 제목으로 가장 적절한 것은?<div class="passage">Walk across almost any college campus or city park and you will find them: narrow strips of bare earth cutting across the grass, worn down by people who chose a shorter route than the paved one. Planners call these “desire lines.” For years, many treated them as a nuisance, putting up fences or signs to keep people on the official paths. These efforts rarely worked; people simply found another way across. Some designers have taken the opposite approach. Instead of paving paths in advance, they plant grass, wait to see where people actually walk, and only then lay down permanent paths along the worn lines. The result is a network that matches how people really move, rather than how a planner imagined they would. A worn strip of grass, in this view, is not damage but valuable information.</div>',
