    body: '다음 글의 제목으로 가장 적절한 것은?<div class="passage">Ask English speakers to describe the smell of coffee, and most will struggle. They tend to name a source (“it smells like coffee”) or to say how they feel about it (“it smells nice”). For a long time, this difficulty was taken as evidence that the human brain is simply poor at putting smells into words. Research among the Jahai, a group of hunter-gatherers living in the rainforests of the Malay Peninsula, has challenged this view. The Jahai language has a set of abstract words for smells, much as English has words like “red” or “blue” for colors, and in one study Jahai speakers named smells about as easily as they named colors. English speakers in the same tests named colors easily but struggled with smells. The problem, it seems, lies less in our noses or brains than in the languages we grow up with.</div>',
