    body: '다음 빈칸에 들어갈 말로 가장 적절한 것은?<div class="passage">Most animals that are hunted by others try hard not to be seen. Their brown, gray, or green coats help them blend into the leaves and soil around them. Yet some small creatures do the opposite. Many poison dart frogs in the rainforests of Central and South America are bright blue, yellow, or red, and they move around in the open during the day. Such boldness makes sense once we learn that their skin contains powerful toxins. A predator that tries to eat one has an unpleasant, sometimes deadly experience, and those that survive learn to connect the bright colors with danger. From then on, they leave such animals alone. For these frogs, being easy to spot is not a weakness but a strategy. Their striking colors serve not to hide them but to ________.</div>',
