    body: '다음 빈칸에 들어갈 말로 가장 적절한 것은?<div class="passage">How do we decide whether an experience was good or bad? We might expect that we simply add up every moment, so that a longer painful experience would always be judged worse than a shorter one. Research suggests otherwise. In one well-known experiment, participants placed a hand in uncomfortably cold water for sixty seconds. In another trial, they did the same, but then kept their hand in the water for an extra thirty seconds while the temperature was raised slightly — still cold, but less painful. When asked which trial they would rather repeat, most chose the longer one, even though it contained more total discomfort. Memory, it appears, does not keep a careful record of how long discomfort lasts. When we look back on an experience, we tend to judge it largely by ________.</div>',
