    body: '다음 빈칸에 들어갈 말로 가장 적절한 것은?<div class="passage">Suppose you come across a gate built across a road, apparently serving no purpose. The obvious reaction is to remove it. The writer G. K. Chesterton argued that this is exactly the wrong response. If you cannot see what the gate is for, he said, you should not tear it down; you should go away and think. Only when you can explain why it was put there may you remove it with a clear conscience. The point applies far beyond gates. Organizations, laws, and traditions are full of rules that look pointless to newcomers. Some really are outdated, but others exist to prevent problems that no one remembers precisely because the rules have worked so well. A reformer who sweeps away every rule he does not understand therefore risks ________.</div>',
