    body: '다음 빈칸에 들어갈 말로 가장 적절한 것은?<div class="passage">A number can be a wonderful tool for understanding a complex situation. A hospital might track how long patients wait in the emergency room, and a school might track how many students pass a test. Trouble begins, however, when people are rewarded or punished according to that number. Suppose a call center decides to judge its staff by the average length of their calls, hoping to encourage efficiency. Before long, some workers may start ending calls quickly, whether or not the customer’s problem has been solved. The figure improves, but the service gets worse. The British economist Charles Goodhart noticed a similar pattern in monetary policy, and his idea is often summarized this way: when a measure becomes a target, it ________.</div>',
