    body: '표는 갑국과 을국이 X재와 Y재를 각각 1개 생산하는 데 필요한 노동 시간을 나타낸 것이다. 이에 대한 설명으로 옳은 것만을 〈보기〉에서 고른 것은? (단, 생산 요소는 노동뿐이며, 두 나라는 비교 우위에 따라 특화하여 교역한다.)<table><tr><th>구분</th><th>X재</th><th>Y재</th></tr><tr><th>갑국</th><td>4시간</td><td>2시간</td></tr><tr><th>을국</th><td>6시간</td><td>12시간</td></tr></table><div class="bogi">ㄱ. 갑국은 두 재화 생산 모두에 절대 우위가 있다.<br>ㄴ. 을국은 X재 생산에 비교 우위가 있다.<br>ㄷ. 갑국에서 Y재 1개 생산의 기회비용은 X재 2개이다.<br>ㄹ. X재 1개와 Y재 1개를 교환하는 조건이라면 두 나라 모두 교역으로 이익을 얻는다.</div>',
