    body: '[1~4] 다음 글을 읽고 물음에 답하시오.<div class="passage" style="font-style:normal">계약은 서로 마주 선 두 개의 의사 표시가 일치함으로써 성립하는 법률 행위이다. 먼저 계약을 맺자고 제안하는 의사 표시를 청약이라 하고, 이에 동의하는 상대방의 의사 표시를 승낙이라 한다. 우리 민법에서 대부분의 계약은 청약과 승낙이 일치하기만 하면 성립하며, 반드시 계약서를 써야 하는 것은 아니다. 계약서는 계약이 성립했다는 사실과 그 내용을 나중에 증명하기 위한 수단인 경우가 많다.<br>청약은 그에 대한 승낙만 있으면 곧바로 계약이 성립할 수 있을 만큼 구체적이고 확정적이어야 한다. 예컨대 ‘이 자전거를 10만 원에 팔겠다.’는 제안은 상대방이 ‘사겠다.’고 답하기만 하면 계약 내용이 모두 정해지므로 청약이 된다. 이와 달리 상대방이 청약을 하도록 꾀는 데 그치는 행위를 청약의 유인이라 한다. 직원을 모집하는 광고가 대표적이다. 광고를 보고 지원한 사람이 청약을 한 것이고, 회사가 그를 채용하겠다고 해야 비로소 계약이 성립한다. 청약의 유인에 응한 것만으로는 계약이 성립하지 않는다는 점에서 둘은 구별된다.<br>청약은 상대방에게 도달한 때 효력이 생기며, 효력이 생긴 뒤에는 청약한 사람이 마음대로 철회하지 못한다. 상대방은 청약을 믿고 승낙할지를 검토하거나 준비를 하므로, 그 신뢰를 보호해야 하기 때문이다. 그러나 청약이 영원히 효력을 갖는 것은 아니다. 승낙 기간을 정한 청약은 그 기간 안에 승낙의 통지를 받지 못하면 효력을 잃는다.<br>승낙은 청약의 내용과 그대로 일치해야 한다. 청약에 조건을 붙이거나 내용을 바꾸어 승낙하면, 민법은 이를 청약을 거절함과 동시에 새로운 청약을 한 것으로 본다. 이때 처음의 청약은 거절되어 효력을 잃으므로, 처음 청약한 사람이 새로운 청약을 승낙해야 비로소 계약이 성립한다.</div>윗글의 내용과 일치하지 <b>않는</b> 것은?',
