    body: '[1~4] 다음 글을 읽고 물음에 답하시오.<div class="passage" style="font-style:normal">밤하늘의 별은 밝기가 저마다 다르다. 고대 그리스의 천문학자 히파르코스는 맨눈으로 보이는 별 가운데 가장 밝은 별들을 1등급, 겨우 보이는 가장 어두운 별들을 6등급으로 하여 별을 여섯 단계로 나누었다. 등급의 숫자가 작을수록 밝은 별이라는 이 전통은 오늘날까지 이어지고 있다.<br>19세기에 들어 별빛의 양을 정밀하게 잴 수 있게 되자, 1등급 별이 6등급 별보다 약 100배 밝다는 사실이 알려졌다. 이를 바탕으로 천문학자들은 등급이 5만큼 차이 나면 밝기가 정확히 100배 차이 나도록 등급을 정의하였다. 그러면 1등급 차이는 밝기로 약 2.5배 차이가 된다. 이렇게 정의하자 1등급보다 밝은 별은 0등급이나 음수 등급으로 나타낼 수 있게 되었다. 밤하늘에서 가장 밝은 별인 시리우스는 약 -1.5등급이고, 태양은 약 -27등급이다.<br>그런데 우리 눈에 보이는 밝기는 별이 실제로 내는 빛의 양뿐 아니라 별까지의 거리에도 영향을 받는다. 같은 양의 빛을 내는 별이라도 거리가 2배 멀어지면 밝기는 4분의 1로, 10배 멀어지면 100분의 1로 줄어든다. 밝기는 거리의 제곱에 반비례하기 때문이다. 이처럼 지구에서 보이는 밝기로 정한 등급을 겉보기 등급이라 한다.<br>겉보기 등급만으로는 어느 별이 실제로 더 많은 빛을 내는지 알 수 없다. 그래서 모든 별을 지구에서 10파섹(약 32.6광년) 떨어진 곳에 옮겨 놓았다고 가정하고 그때의 밝기로 등급을 정하는데, 이를 절대 등급이라 한다. 절대 등급이 작을수록 실제로 빛을 많이 내는 별이다. 태양은 겉보기 등급으로는 다른 어떤 별보다 밝지만, 절대 등급은 약 4.8등급으로 평범한 별에 속한다.</div>윗글의 내용과 일치하지 <b>않는</b> 것은?',
    type: 'choice',
