    body: '다음 글을 읽고 물음에 답하시오.<div class="passage" style="font-style:normal">삼촌은 그날 저녁에도 마루 끝에 앉아 구두를 닦았다. 이미 반짝이는 구두였다. 나는 숙제를 하는 척하며 삼촌의 손을 훔쳐보았다. 솔이 같은 자리를 몇 번이고 오갔다. 할머니가 밥상을 들고 나오며 “내일이냐?” 하고 물었을 때, 삼촌은 고개도 들지 않고 “예.” 하고만 대답했다. 나는 삼촌이 무엇을 기다리는지 알지 못했다. 다만 그 구두가 내일 아침 어딘가 먼 곳으로 걸어갈 것만 같았다.<br><span style="float:right">- 연습용 글</span><br></div>윗글의 서술상 특징으로 가장 적절한 것은?',
