    body: '[1~4] 다음 글을 읽고 물음에 답하시오.<div class="passage" style="font-style:normal">물가가 지나치게 빠르게 오르면 같은 돈으로 살 수 있는 물건이 줄어들어 사람들의 생활이 어려워진다. 그래서 많은 나라의 중앙은행은 물가 안정을 중요한 목표로 삼고, 그 수단으로 기준 금리를 활용한다. 우리나라에서는 한국은행의 금융통화위원회가 기준 금리를 정한다. 기준 금리는 중앙은행이 금융 기관과 거래할 때 기준이 되는 금리로, 이것이 바뀌면 은행의 예금 금리와 대출 금리 같은 시중 금리도 대체로 같은 방향으로 움직인다.<br>물가가 목표보다 높게 오를 것으로 예상되면 중앙은행은 기준 금리를 올린다. 시중 금리가 오르면 돈을 빌리는 데 드는 비용이 커지므로 가계는 대출을 받아 소비하기를 망설이고, 기업도 빌린 돈으로 하는 투자를 줄인다. 반대로 예금 이자는 늘어나므로 사람들은 지금 쓰기보다 저축을 늘리려 한다. 이렇게 경제 전체에서 물건과 서비스를 사려는 수요가 줄면 물가 상승 압력이 약해진다. 또한 다른 나라보다 금리가 높아지면 더 높은 수익을 찾는 외국 자금이 들어와 자국 화폐의 가치가 오를 수 있다. 화폐 가치가 오르면 같은 양의 외국 물건을 더 적은 자국 화폐로 살 수 있으므로 수입 물가가 낮아지는 효과도 생긴다. 반대로 경기가 침체하여 물가가 목표보다 낮을 것으로 보이면 중앙은행은 기준 금리를 내려 소비와 투자를 북돋운다.<br>그러나 기준 금리 조정에는 한계도 있다. 우선 금리를 바꾼 효과가 실물 경제에 나타나기까지는 상당한 시간이 걸린다. 그래서 중앙은행은 현재의 물가만이 아니라 앞으로의 물가를 예측하여 미리 움직여야 한다. 또 금리를 올려 물가를 잡으려다 소비와 투자가 지나치게 위축되면 경기가 나빠지고 일자리가 줄어들 수 있다. 특히 원유 가격 급등처럼 공급 쪽의 충격으로 물가가 오를 때에는, 금리 인상이 물가를 낮추는 효과는 제한적이면서 경기만 더 둔화시킬 위험이 있다. 중앙은행이 금리를 결정할 때 물가와 경기 사이에서 신중하게 균형을 잡으려는 까닭이 여기에 있다.</div>윗글의 내용과 일치하지 <b>않는</b> 것은?',
