    slot: '독서 · 세트 7 (1/3) · 내용 일치',
    body: '[1~3] 다음 글을 읽고 물음에 답하시오.<div class="passage" style="font-style:normal">자율 주행 자동차나 로봇이 주변을 파악하려면 물체가 얼마나 떨어져 있는지 정확히 알아야 한다. 이때 널리 쓰이는 장치가 라이다(LiDAR)이다. 라이다는 레이저 빛을 짧은 펄스 형태로 쏜 뒤, 그 빛이 물체에 부딪혀 되돌아오기까지 걸린 시간을 재어 거리를 계산한다. 이러한 방식을 비행시간(ToF) 측정이라고 한다.<br>빛은 1초에 약 30만 km, 즉 약 3억 m를 나아간다. 측정된 시간은 빛이 물체까지 갔다가 돌아온 왕복 시간이므로, 거리는 빛의 속력에 측정 시간을 곱한 뒤 2로 나누어 구한다. 예를 들어 빛이 돌아오기까지 1마이크로초(100만분의 1초)가 걸렸다면, 빛은 그동안 약 300m를 이동했으므로 물체까지의 거리는 약 150m이다. 빛이 매우 빠르기 때문에 라이다는 10억분의 1초 단위의 아주 짧은 시간까지 정밀하게 재야 한다. 시간 측정에 10억분의 1초의 오차만 생겨도 거리는 약 15cm나 달라진다.<br>라이다는 한 방향만 재지 않는다. 장치를 회전시키거나 빛의 방향을 빠르게 바꾸면서 1초에 수십만 번 이상 펄스를 쏘아 각 방향의 거리 값을 모은다. 이렇게 얻은 수많은 점은 저마다 공간 속 위치를 지니므로, 이를 모으면 주변 환경을 입체적으로 나타낸 점 구름(point cloud)이 만들어진다.<br>라이다는 스스로 빛을 내보내 측정하므로, 주변의 빛에 의존하는 카메라와 달리 어두운 곳에서도 거리를 잴 수 있다. 또 전파를 쓰는 레이더보다 파장이 훨씬 짧은 빛을 쓰기 때문에 물체의 모양을 더 세밀하게 파악할 수 있다. 하지만 빛은 빗방울이나 안개 입자에 쉽게 흩어지기 때문에, 날씨가 나쁠 때에는 레이더보다 측정 성능이 떨어지기 쉽다. 그래서 자율 주행 자동차는 라이다, 레이더, 카메라를 함께 사용하여 서로의 약점을 보완한다.</div>윗글의 내용과 일치하는 것은?',
