    level: 3,
    slot: '독서 · 세트 8 (3/3) · 개념 이해',
    body: '[1~3] 다음 글을 읽고 물음에 답하시오.<div class="passage" style="font-style:normal">어떤 대상을 보고 ‘아름답다’고 말할 때, 우리는 무엇을 판단하는 것일까? 18세기 독일 철학자 칸트는 『판단력 비판』에서 이 물음을 다루며, 아름다움에 대한 판단을 다른 종류의 만족과 구별하였다.<br>칸트에 따르면 우리가 대상에서 만족을 느끼는 경우는 세 가지로 나눌 수 있다. 첫째는 쾌적한 것에 대한 만족이다. 더운 날 마시는 시원한 물이 좋은 것은 그것이 감각적 욕구를 채워 주기 때문이다. 둘째는 좋은 것에 대한 만족이다. 튼튼한 다리나 올바른 행동이 좋다고 할 때 우리는 그것이 어떤 목적에 쓸모 있는지, 도덕적으로 옳은지를 개념에 비추어 판단한다. 이 두 가지 만족은 모두 대상이 실제로 존재하는 것과 관련된 관심을 품고 있다. 목마른 사람에게는 그림 속의 물이 아니라 실제로 마실 수 있는 물이 필요하고, 다리의 쓸모를 따지는 사람에게는 그 다리가 실제로 놓여 있어야 의미가 있다.<br>셋째가 아름다운 것에 대한 만족이다. 칸트는 이 만족이 ‘무관심적’이라고 보았다. 여기서 무관심이란 대상에 흥미가 없다는 뜻이 아니라, 대상을 소유하거나 이용하려는 욕구, 그리고 그것이 실제로 존재하는지에 대한 관심과 상관없이 대상의 모습 그 자체를 바라보며 만족을 느낀다는 뜻이다. 예컨대 어떤 궁전을 보고 아름다운지 판단할 때, 그 궁전을 짓느라 들어간 막대한 비용을 비판하거나 그곳에 살고 싶어 하는 마음은 아름다움에 대한 판단과는 관계가 없다.<br>칸트는 이 무관심성에서 아름다움에 대한 판단의 또 다른 특징을 이끌어 냈다. 쾌적함은 개인의 감각과 욕구에 달려 있으므로 ‘나에게는 쾌적하다’고 말하면 충분하고, 남에게 동의를 요구하지 않는다. 그러나 아름다움에 대한 판단은 개인적인 욕구나 이해관계에서 벗어나 있기 때문에, 판단하는 사람은 다른 사람들도 같은 판단에 동의해야 한다고 여긴다. 다만 이 보편성은 개념으로 증명될 수 있는 것이 아니라는 점에서 ‘주관적 보편성’이라 불린다.</div>윗글에서 아름다움에 대한 판단의 보편성을 ‘주관적 보편성’이라고 부르는 까닭으로 가장 적절한 것은?',
