    body: '다음 글의 목적으로 가장 적절한 것은?<div class="passage">Dear Local Business Owners,<br>My name is Sora Han, and I direct the student band at Greenfield Middle School. This year, more students than ever have signed up to join the band, which is wonderful news. However, it has also created a problem. Our school owns only twenty instruments, and many of them are over fifteen years old. As a result, several new members have been sharing a single flute or waiting their turn during practice instead of playing. Many of their families cannot afford to buy instruments of their own. If your store or office has any used instruments sitting in a storage room, we would be deeply grateful if you would donate them to our band. Even instruments that need minor repairs are welcome, as a local music shop has kindly offered to fix them for free.<br>Best regards,<br>Sora Han</div>',
