    slot: '주장',
    body: '다음 글에서 필자가 주장하는 바로 가장 적절한 것은?<div class="passage">Many parents today fill every hour of their children’s week with lessons, sports, and tutoring, as if an empty afternoon were a waste. Their intentions are good: they want their children to develop skills and stay out of trouble. But a schedule with no gaps quietly takes something away. When children have nothing planned, they must decide for themselves what to do. At first they may complain of boredom, yet boredom is often the push that leads them to invent a game, start a drawing, or take apart an old radio to see how it works. In these moments they learn to follow their own curiosity and to entertain themselves without an adult directing them. Such abilities cannot be taught in a class. Parents should therefore leave regular stretches of free time in their children’s schedules instead of filling every hour.</div>',
