    slot: '주장',
    body: '다음 글에서 필자가 주장하는 바로 가장 적절한 것은?<div class="passage">When a decision turns out badly, we tend to conclude that it was a bad decision, and when it turns out well, we praise our own wisdom. But outcomes are shaped by luck as well as by judgment. A smart choice can end in failure, and a careless one can succeed by chance. The trouble is that once we know how things turned out, our memory of what we were thinking quietly changes. We remember having been more certain, or more doubtful, than we really were. To learn honestly from experience, write down your reasoning before you know the result. Note what you decided, why you decided it, and what you expected to happen. Later, compare the record with the outcome. Only then can you tell whether you were wise or merely lucky, and improve the way you make decisions rather than just reacting to results.</div>',
