    body: '밑줄 친 <u>sharpening pencils for a letter we never write</u>가 다음 글에서 의미하는 바로 가장 적절한 것은?<div class="passage">Faced with a difficult task, such as writing a report or preparing for a hard exam, many of us suddenly become remarkably busy. We clean our desks, reorganize our files, answer old emails, and make detailed plans with color-coded schedules. All of this feels productive, and in a narrow sense it is: each small job really gets done. But these jobs share a convenient feature. They are easy, they have clear endings, and none of them requires us to face the uncertain, uncomfortable work that actually matters. At the end of such a day we feel tired and even satisfied, yet the report remains unwritten. We have spent the day <u>sharpening pencils for a letter we never write</u>. Real progress usually begins only when we notice this pattern and give the hardest task the first and freshest hours of the day.</div>',
