    body: '밑줄 친 <u>built in drops and lost in buckets</u>가 다음 글에서 의미하는 바로 가장 적절한 것은?<div class="passage">A shop owner may spend twenty years earning the trust of her customers. She gives honest advice, admits when a product is not right for someone, and fixes her mistakes without argument. No single one of these acts seems important, and customers barely notice them. Yet over time they add up, and people begin to recommend her without hesitation. Now imagine that one day she is caught selling a damaged item as new. Within weeks, the story spreads, and many loyal customers start shopping elsewhere. Two decades of quiet effort can be undone by a single dishonest act. This imbalance is why trust deserves such careful protection: it is <u>built in drops and lost in buckets</u>. Anyone who depends on the confidence of others, whether a business, a teacher, or a friend, would do well to remember it.</div>',
