    body: '다음 글의 요지로 가장 적절한 것은?<div class="passage">Many people believe that writing is simply the final step of thinking: first you figure out what you believe, and then you put it into words. In practice, the relationship often works the other way around. Ideas that feel clear and complete in our heads frequently fall apart the moment we try to write them down. A sentence refuses to connect to the next, an example turns out not to support the point, or a step we skipped over turns out to be the weakest part of the argument. These moments are frustrating, but they are exactly what make writing valuable. The page shows us the gaps that our minds had smoothly covered over. By struggling to express an idea, we are forced to examine it, repair it, and sometimes discover that we believed something different from what we thought.</div>',
