    slot: '글의 요지',
    body: '다음 글의 요지로 가장 적절한 것은?<div class="passage">It is natural to measure our progress by looking at the people around us. A student checks where she ranks in her class; a runner compares his time with that of his teammates. Yet such comparisons often tell us less than we think. The people we compare ourselves with started at different points, have different amounts of time, and face different obstacles. Someone will almost always be ahead, so the comparison can leave us discouraged even when we are improving steadily. A more useful measure is the person we were a month or a year ago. Did we understand this chapter last spring? Could we run this distance last summer? Comparing ourselves with our past selves shows real growth, points to what we still need to work on, and keeps us motivated in a way that comparing ourselves with others rarely does.</div>',
