    body: '다음 글의 주제로 가장 적절한 것은?<div class="passage">Look at a map of the world’s oldest cities and you will notice that a great many of them sit beside rivers. This is no accident. A river provided a steady supply of fresh water for drinking, cooking, and washing, needs that no settlement could do without. The floods that many rivers brought each year spread rich soil across the surrounding land, allowing farmers to grow enough food to support large populations. Rivers also served as natural highways. Long before paved roads existed, boats could carry heavy goods such as grain, stone, and timber far more cheaply than animals or people could carry them over land. Towns along a river could therefore trade with distant places, and trade brought wealth, new ideas, and still more people. Over centuries, these advantages turned small riverside villages into great cities.</div>',
