    body: '다음 글의 제목으로 가장 적절한 것은?<div class="passage">Imagine you bought an expensive concert ticket weeks ago, but on the day of the show you have a bad cold and the weather is terrible. Staying home sounds far more pleasant, yet many people go anyway, telling themselves, “I already paid for it.” The money, however, is gone whether they go or not. The only real question is which choice will make the evening better from now on. The same mistake appears on a larger scale. Companies keep funding failing projects because so much has already been invested, and people stay in courses they dislike because they have already spent a year on them. In each case, past costs that cannot be recovered are allowed to drive decisions about the future. A wiser approach is to ask a simple question: knowing what I know now, would I start this today?</div>',
