    body: '다음 빈칸에 들어갈 말로 가장 적절한 것은?<div class="passage">In a well-known line of research, chess masters and beginners were shown a chessboard from a real game for just a few seconds and then asked to rebuild the position from memory. The masters placed most of the pieces correctly, while the beginners managed only a few. It might seem that the masters simply had better memories. But when the pieces were placed randomly on the board, in arrangements that could never occur in a real game, the masters’ advantage largely disappeared. Their skill, it turned out, did not lie in remembering more pieces but in seeing the board in larger units. Years of play had taught them to recognize familiar groups of pieces as single patterns, much as a reader sees a word rather than a string of letters. Expertise, in this sense, depends on ________.</div>',
