    body: '다음 글의 밑줄 친 부분 중, 문맥상 낱말의 쓰임이 적절하지 <b>않은</b> 것은?<div class="passage">Birds rely on song to attract mates and to <u>① defend</u> their territories, so being heard is essential. In cities, however, their songs must compete with the constant noise of traffic, which is mostly low in pitch. Researchers have found that in some species, birds living in noisy urban areas sing at a <u>② higher</u> pitch than members of the same species in quieter places. By shifting their songs upward, away from the low rumble of engines, they make their calls easier to <u>③ distinguish</u> from the background noise. Some birds also sing more loudly, or <u>④ avoid</u> the busiest hours by starting to sing earlier in the morning. These changes suggest that birds can <u>⑤ resist</u> their behavior to a changing environment, although it is not yet clear whether such adjustments fully make up for the effects of noise.</div>',
