    body: '다음은 사상가 A, B의 주장이다. 이에 대한 설명으로 옳은 것만을 〈보기〉에서 고른 것은?<div class="bogi">A: 어떤 것이 생명 공동체의 온전함, 안정성, 아름다움을 보전하는 경향이 있으면 옳고, 그렇지 않으면 그르다. 인간은 대지 공동체의 정복자가 아니라 평범한 구성원이다.<br>B: 아는 것이 힘이다. 인간은 자연에 대한 지식을 통해 자연을 지배하고 인간의 삶을 풍요롭게 할 수 있다.</div><div class="bogi">ㄱ. A는 대지 윤리를 주장한 레오폴드의 입장이다.<br>ㄴ. A는 개별 생명체뿐 아니라 생태계 전체를 도덕적 고려의 대상으로 본다.<br>ㄷ. B는 자연을 인간의 이익을 위한 도구로 여긴다.<br>ㄹ. B는 인간과 자연을 하나의 유기적 전체로 보는 전일론적 관점을 지닌다.</div>',
